import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp_moves = [o for _, o in history]
    my_moves = [m for m, _ in history]
    opp_c = sum(1 for o in opp_moves if o == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for m in my_moves if m == 'D')

    last_me, last_opp = history[-1]

    # Late-game exploitation against highly cooperative opponents.
    if n >= 96:
        if opp_d == 0:
            return 'D'
        if opp_d * 3 <= n:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Very cooperative opponent: stay cooperative, avoid needless defection.
    if opp_d <= 1:
        return 'C'

    # Heavily defection-heavy opponent: minimize losses.
    if opp_d * 2 > n:
        if last_opp == 'C' and n >= 3 and opp_moves[-2] == 'C' and opp_moves[-3] == 'C':
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    # Count recent opponent behavior.
    w = 8 if n >= 8 else n
    recent_opp = opp_moves[-w:]
    recent_d = sum(1 for o in recent_opp if o == 'D')
    recent_c = w - recent_d

    # Strong sustained defection in recent window: punish.
    if recent_d >= 6 and w >= 6:
        return 'D'

    # Long cooperation streak: cooperate, occasional probe if safely ahead.
    if recent_d == 0:
        if n < 90 and my_d < 3 and n > 20 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Opponent just defected after we cooperated: retaliate immediately.
    if last_opp == 'D' and last_me == 'C':
        return 'D'

    # Opponent just cooperated after we defected: extend olive branch.
    if last_opp == 'C' and last_me == 'D':
        return 'C' if rng.random() < 0.85 else 'D'

    # Moderate defection rate: mostly retaliate but forgive occasionally.
    if recent_d <= 2:
        return 'C'

    if last_opp == 'D':
        if recent_d >= 4:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    return 'C'
